package app
import("bytes";"encoding/json";"net/http/httptest";"testing")
func callProtocol(t *testing.T,a *App,payload string)map[string]any{t.Helper();r:=httptest.NewRequest("POST","https://example.com/mcp",bytes.NewBufferString(payload));r.Header.Set("Content-Type","application/json");r.Header.Set("Accept","application/json, text/event-stream");r.Header.Set("MCP-Protocol-Version","2025-11-25");w:=httptest.NewRecorder();a.Handler().ServeHTTP(w,r);if w.Code!=200{t.Fatalf("HTTP%d: %s",w.Code,w.Body.String())};var out map[string]any;if e:=json.Unmarshal(w.Body.Bytes(),&out);e!=nil{t.Fatal(e,w.Body.String())};return out}
func TestActualToolRegistryAndAnnotations(t *testing.T){a:=&App{};out:=callProtocol(t,a,`{"jsonrpc":"2.0","id":1,"method":"tools/list","params":{}}`);r,ok:=out["result"].(map[string]any);if !ok{t.Fatal(out)};tools,ok:=r["tools"].([]any);if !ok||len(tools)!=17{t.Fatalf("tool count: %v",r)};seen:=map[string]bool{};for _,v:=range tools{x:=v.(map[string]any);name:=x["name"].(string);if seen[name]{t.Fatal("duplicate tool",name)};seen[name]=true;ann:=x["annotations"].(map[string]any);if name=="mail_send_confirmed"{if ann["readOnlyHint"]!=false||ann["destructiveHint"]!=true||ann["openWorldHint"]!=true{t.Fatal(ann)}};if name=="mail_read"&&ann["readOnlyHint"]!=true{t.Fatal(ann)}};if !seen["mail_get_attachment"]||!seen["mail_save_draft"]{t.Fatal(seen)}}
func TestMissingScopeReturnsChallengeWithoutBackend(t *testing.T){a:=&App{AuthChallenge:func(string)string{return `Bearer scope="mail.read mail.send"`}};out:=callProtocol(t,a,`{"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"mail_send_confirmed","arguments":{"prepared_id":"x","confirmed_digest":"y","append_sent":false}}}`);r,ok:=out["result"].(map[string]any);if !ok||r["isError"]!=true{t.Fatal(out)};meta,ok:=r["_meta"].(map[string]any);if !ok||meta["mcp/www_authenticate"]==nil{t.Fatal("missing OAuth challenge",out)}}
